components.css:
.ds-btn-green{display:inline-block;border:none;cursor:pointer;font-family:var(--font-sans, 'DM Sans', Inter, system-ui, sans-serif);font-size:1rem;font-weight:600;line-height:1.5rem;padding:12px 24px;border-radius:9999px;transition:color .2s,background-color .2s,border-color .2s;background:var(--color-green-mid, #526855);color:var(--color-paper, #ffffff);box-shadow:0 1px 3px 0 rgb(37 37 37 / 5%);}
.ds-btn-green:hover{background:var(--color-green, #384033);}
.ds-btn-green:focus-visible{outline:2px solid var(--color-green, #384033);outline-offset:2px;}

.ds-btn-outline{display:inline-block;border:none;cursor:pointer;font-family:var(--font-sans, 'DM Sans', Inter, system-ui, sans-serif);font-size:1rem;font-weight:600;line-height:1.5rem;padding:12px 24px;border-radius:9999px;transition:color .2s,background-color .2s,border-color .2s;background:transparent;color:var(--color-ink-soft, #5c5c5c);border:1px solid color-mix(in srgb, var(--color-green-mid, #526855) 40%, transparent);}
.ds-btn-outline:hover{border-color:var(--color-green-mid, #526855);color:var(--color-green-mid, #526855);}
.ds-btn-outline:focus-visible{outline:2px solid var(--color-green-mid, #526855);outline-offset:2px;}

.ds-quiz-stack{display:flex;flex-direction:column;gap:8px;font-family:var(--font-sans, 'DM Sans', Inter, system-ui, sans-serif);max-width:420px;}
.ds-quiz-option{position:relative;overflow:hidden;border-radius:12px;border:1px solid color-mix(in srgb, var(--color-ink, #252525) 10%, transparent);padding:12px 16px;text-align:left;font-size:.875rem;line-height:1.25rem;background:transparent;color:var(--color-ink-soft, #5c5c5c);cursor:pointer;transition:color .2s,border-color .2s;}
.ds-quiz-option::before{content:"";position:absolute;inset:0;transform-origin:left;transform:scaleX(0);background:var(--color-green-soft, #e8ece7);transition:transform .28s cubic-bezier(.16,1,.3,1);}
.ds-quiz-option>span{position:relative;}
.ds-quiz-option:hover{border-color:color-mix(in srgb, var(--color-green-mid, #526855) 50%, transparent);}
.ds-quiz-option.is-selected{border-color:var(--color-green-mid, #526855);color:var(--color-ink, #252525);}
.ds-quiz-option.is-selected::before{transform:scaleX(1);}
.ds-quiz-option:focus-visible{outline:2px solid var(--color-green-mid, #526855);outline-offset:2px;}

.ds-divider{display:flex;align-items:center;gap:16px;font-family:var(--font-sans, 'DM Sans', Inter, system-ui, sans-serif);color:var(--color-gold-dark, #a15c17);}
.ds-divider::before,.ds-divider::after{content:"";height:1px;flex:1;background:color-mix(in srgb, var(--color-gold, #ca9e52) 40%, transparent);}
.ds-divider h2{margin:0;min-width:0;font-size:1.5rem;line-height:2rem;font-weight:700;color:var(--color-ink, #252525);}
